<?php if(!defined('ABSPATH')){exit;}$article=$state->article();$post=get_post(absint($article['wordpress_post_id']??0));$attachment=absint($article['featured_image_attachment_id']??0);$edit=$post&&current_user_can('edit_post',$post->ID)?get_edit_post_link($post->ID,''):'';$preview=$post?get_preview_post_link($post):'';$published=$post&&'publish'===$post->post_status?get_permalink($post):'';$analysis=is_array($article['seo_analysis']??null)?$article['seo_analysis']:array(); ?>
<div class="aics-wizard-complete"><header class="aics-wizard-step-header"><p class="aics-eyebrow"><?php esc_html_e('Step 6 of 6','ai-content-studio');?></p><h2 tabindex="-1"><?php esc_html_e('Your Draft Is Ready','ai-content-studio');?></h2><p><?php esc_html_e('Open the WordPress editor to complete the final editorial review and publish it.','ai-content-studio');?></p></header><div class="aics-final-preview"><?php if($attachment):?><?php echo wp_get_attachment_image($attachment,'large',false,array('class'=>'aics-final-image'));?><?php endif;?><div><span class="aics-status-badge"><?php echo esc_html($post?ucfirst($post->post_status):__('Unavailable','ai-content-studio'));?></span><h3><?php echo esc_html($article['title']);?></h3><p><?php echo esc_html($article['excerpt']);?></p><dl class="aics-final-meta"><div><dt><?php esc_html_e('SEO adapter','ai-content-studio');?></dt><dd><?php echo esc_html($article['seo_adapter']?:$article['seo_target_plugin']);?></dd></div><div><dt><?php esc_html_e('Focus keyword','ai-content-studio');?></dt><dd><?php echo esc_html($article['seo_focus_keyword']);?></dd></div><div><dt><?php esc_html_e('SEO Readiness','ai-content-studio');?></dt><dd><?php echo esc_html(absint($analysis['score']??0).'/100');?></dd></div><div><dt><?php esc_html_e('Updated','ai-content-studio');?></dt><dd><?php echo esc_html(get_date_from_gmt($article['updated_at'],get_option('date_format').' '.get_option('time_format')));?></dd></div></dl></div></div><?php if($preview):?><div class="aics-preview-frame-wrap"><div class="aics-preview-loading"><?php esc_html_e('Loading WordPress preview…','ai-content-studio');?></div><iframe class="aics-preview-frame" title="<?php esc_attr_e('WordPress post preview','ai-content-studio');?>" src="<?php echo esc_url($preview);?>" loading="lazy"></iframe></div><?php endif;?><footer class="aics-wizard-actions"><?php if($edit):?><a class="button button-primary" href="<?php echo esc_url($edit);?>"><?php esc_html_e('Edit Post','ai-content-studio');?></a><?php endif;?><?php if($preview):?><a class="button" target="_blank" rel="noopener" href="<?php echo esc_url($preview);?>"><?php esc_html_e('Open Full Preview','ai-content-studio');?></a><?php endif;?><?php if($published):?><a class="button" href="<?php echo esc_url($published);?>"><?php esc_html_e('View Post','ai-content-studio');?></a><?php endif;?><button class="button aics-button-danger" type="button" data-aics-reset><?php esc_html_e('Start New Content','ai-content-studio');?></button></footer></div>
